int fibonacci(int n) 
{ 
    // Base case 
    if (n == 0) 
        return 0; 
    // Recursive case 
    else if (n == 1) 
        return 1; 
    else 
        return fibonacci(n - 1) + fibonacci(n - 2); 
} 

